<#
.SYNOPSIS
  Regenerates tests/fixtures/packs/extra-pack: a conforming, clearly test-only pack (95 printable ASCII glyphs
  plus U+FFFD) made of simple 3x5 block glyphs. Used to prove that a new pack registers without engine changes.
#>
$ErrorActionPreference = 'Stop'
$dir = Join-Path $PSScriptRoot 'extra-pack'
$glyphs = Join-Path $dir 'glyphs'
if (Test-Path $dir) { Remove-Item -Recurse -Force $dir }
New-Item -ItemType Directory -Force $glyphs | Out-Null

$utf8 = New-Object System.Text.UTF8Encoding($false)
$manifest = @'
font-pack {
  --schema: "pixelcss-pack/1";
  --id: "extra-pack";
  --display-name: "Extra Test Pack";
  --style-description: "Test-only 3x5 block glyphs";
  --version: "0.0.1";
  --authenticity: "style-interpretation";
  --origin: "Generated by tests/fixtures/packs/make_extra_pack.ps1";
  --author: "PixelCSS contributors";
  --license: "OFL-1.1";
  --license-file: "LICENSE.txt";
  --line-height: 7;
  --ascent: 5;
  --descent: 1;
  --coverage: U+0020-007E, U+FFFD;
  --aliases: "Extra Test Pack";
  --order: 50;
}
'@
[IO.File]::WriteAllText((Join-Path $dir 'manifest.css'), $manifest.Replace("`r`n", "`n"), $utf8)
[IO.File]::WriteAllText((Join-Path $dir 'LICENSE.txt'), "Test fixture. SIL Open Font License 1.1 applies.`n", $utf8)

$codePoints = @(0x20..0x7E) + 0xFFFD
foreach ($cp in $codePoints) {
    $hex = '{0:X4}' -f $cp
    if ($cp -eq 0x20) {
        $body = "glyph {`n  --schema: `"pixelcss-glyph/1`";`n  --code-point: U+$hex;`n  --family: `"extra-pack`";`n  --width: 0;`n  --height: 0;`n  --baseline: 0;`n  --advance: 4;`n}`n"
    } else {
        $rows = '    "@ @ @"' + "`n" + '    "@ . @"' + "`n" + '    "@ @ @"' + "`n" + '    "@ . @"' + "`n" + '    "@ @ @";'
        $body = "glyph {`n  --schema: `"pixelcss-glyph/1`";`n  --code-point: U+$hex;`n  --family: `"extra-pack`";`n  --width: 3;`n  --height: 5;`n  --baseline: 5;`n  --advance: 4;`n  --rows:`n$rows`n}`n"
    }
    [IO.File]::WriteAllText((Join-Path $glyphs "U+$hex.css"), $body, $utf8)
}
"extra-pack: $($codePoints.Count) glyph files"
